const { editWithRunware } = require('./dist/providers/runware.js');
const { editWithReplicate } = require('./dist/providers/replicate.js');
const { editWithAtlas } = require('./dist/providers/atlas.js');

// API keys are read from environment (.env). Do NOT hardcode secrets here.
// Run with: RUNWARE_API_KEY=... REPLICATE_API_TOKEN=... ATLAS_API_KEY=... node test_all.js
require('dotenv').config();
if (!process.env.RUNWARE_API_KEY || !process.env.REPLICATE_API_TOKEN || !process.env.ATLAS_API_KEY) {
  console.warn('[test_all] One or more provider API keys missing from environment.');
}

const testImage = 'data:image/jpeg;base64,';

const modelsToTest = {
  runware: [
    'runware:106@1',
    'runware:101@1',
    'bytedance:seedream@4.5',
    'alibaba:wan@2.7-image-pro'
  ],
  replicate: [
    'black-forest-labs/flux-kontext-pro',
    'black-forest-labs/flux-fill-pro',
    'stability-ai/stable-diffusion-3-medium'
  ],
  atlas: [
    'flux-kontext-pro',
    'bytedance/doubao-seed-evolving',
    'alibaba/wan-2.7-image',
    'xai/grok-imagine',
    'google/gemini-3.1-flash-image'
  ]
};

async function testProvider(providerName, models, editFn) {
  console.log(`\n--- Testing ${providerName} ---`);
  for (const model of models) {
    console.log(`[${providerName}] Testing model: ${model}...`);
    try {
      const result = await editFn({
        imageBase64: testImage,
        prompt: 'a tiny red dot',
        model: model,
        provider: providerName,
        strength: 0.5,
        steps: 10
      });
      console.log(`  ✅ SUCCESS: Got image -> ${result.imageUrl ? result.imageUrl.substring(0, 50) + '...' : 'Base64 data'}`);
    } catch (err) {
      console.error(`  ❌ FAILED: ${err.message}`);
    }
  }
}

async function runAllTests() {
  await testProvider('runware', modelsToTest.runware, editWithRunware);
  await testProvider('replicate', modelsToTest.replicate, editWithReplicate);
  await testProvider('atlas', modelsToTest.atlas, editWithAtlas);
  console.log('\n--- ALL TESTS FINISHED ---');
}

runAllTests().catch(console.error);
